const authAttempts=new Map<string,{count:number;reset:number}>();
app.use(['/api/auth/login','/api/auth/register'],(req,res,next)=>{const key=req.ip||'unknown',now=Date.now(),current=authAttempts.get(key);if(!current||current.reset<now){authAttempts.set(key,{count:1,reset:now+15*60_000});return next()}if(current.count>=30)return res.status(429).json({error:'Слишком много попыток. Повторите через несколько минут'});current.count++;next()});

type AuthRequest = Request & { user?: { id: string; role: Role; organizationId?: string } };
const asyncRoute = (fn:(req:AuthRequest,res:Response,next:NextFunction)=>Promise<unknown>) => (req:AuthRequest,res:Response,next:NextFunction)=>Promise.resolve(fn(req,res,next)).catch(next);
const tokenFor = (user:{id:string;role:Role;organizationId:string|null}) => jwt.sign({ id:user.id,role:user.role,organizationId:user.organizationId || undefined },secret,{expiresIn:'7d'});
const setSession = (res:Response,token:string) => res.cookie('iui_session',token,{httpOnly:true,sameSite:'lax',secure:production,maxAge:7*24*60*60*1000,path:'/'});
const auth = (req:AuthRequest,res:Response,next:NextFunction) => {try{const token=req.cookies.iui_session || req.headers.authorization?.replace('Bearer ','');if(!token)return res.status(401).json({error:'Требуется авторизация'});req.user=jwt.verify(token,secret) as any;next()}catch{return res.status(401).json({error:'Сессия истекла'})}};
const requireTeacher = (req:AuthRequest,res:Response,next:NextFunction) => req.user?.role==='TEACHER'||req.user?.role==='ADMIN'?next():res.status(403).json({error:'Недостаточно прав'});
const requireStudent = (req:AuthRequest,res:Response,next:NextFunction) => req.user?.role==='STUDENT'?next():res.status(403).json({error:'EEG-сессию запускает ученик из своего кабинета'});
const makeClassCode=()=>`CLASS-${crypto.randomUUID().slice(0,4).toUpperCase()}-${crypto.randomUUID().slice(0,4).toUpperCase()}`;
const schoolDayKey=(date=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Aqtau',year:'numeric',month:'2-digit',day:'2-digit'}).format(date);
const schoolDayStart=(date=new Date())=>new Date(`${schoolDayKey(date)}T00:00:00+05:00`);
const schoolDayDistance=(later:Date,earlier:Date)=>Math.round((schoolDayStart(later).getTime()-schoolDayStart(earlier).getTime())/86400000);
const currentFirmware='1.2.0';
const firmwareStatus=(version:string)=>{if(!/^\d+\.\d+\.\d+$/.test(version))return 'UNKNOWN';const parts=version.split('.').map(Number),required=currentFirmware.split('.').map(Number);for(let index=0;index<3;index++){if(parts[index]>required[index])return 'NEWER';if(parts[index]<required[index])return 'OUTDATED'}return 'CURRENT'};

const sessionScope=async(req:AuthRequest)=>{
  if(req.user!.role==='STUDENT')return {student:{userId:req.user!.id}};
  if(req.user!.role==='PARENT'){
    const parent=await prisma.user.findUnique({where:{id:req.user!.id},select:{email:true,parentStudentId:true}});
    const invitation=!parent?.parentStudentId&&parent?.email?await prisma.invite.findFirst({where:{organizationId:req.user!.organizationId,role:Role.PARENT,email:parent.email},orderBy:{createdAt:'desc'},select:{studentId:true}}):null;
    return {studentId:parent?.parentStudentId||invitation?.studentId||'__unlinked__'};
  }
  return {student:{class:{organizationId:req.user!.organizationId}}};
};
const liveStreak=(student:{streak:number;lastHomeworkAt?:Date|null})=>!student.lastHomeworkAt?student.streak:schoolDayDistance(new Date(),student.lastHomeworkAt)<=1?student.streak:0;
const familyStudentId=async(req:AuthRequest)=>req.user!.role==='STUDENT'?(await prisma.student.findUnique({where:{userId:req.user!.id},select:{id:true}}))?.id:(await prisma.user.findUnique({where:{id:req.user!.id},select:{parentStudentId:true}}))?.parentStudentId;
const neuroFocusFromSession=(session:{attentionAvg?:number|null;focusAvg?:number|null;engagementAvg?:number|null;relaxationAvg?:number|null;signalAvg?:number|null;fatigueScore?:number|null})=>{
  const focus:string[]=[];
  if((session.focusAvg||0)<68||((session.attentionAvg||0)<68))focus.push('Устойчивый фокус');
  if((session.fatigueScore||0)>=60||(session.relaxationAvg||0)<45)focus.push('Когнитивное восстановление');
  if((session.engagementAvg||0)<65)focus.push('Избирательное внимание');
  if((session.signalAvg||100)<55)focus.push('Спокойная посадка и качество сигнала');
  if(!focus.length)focus.push('Поддержание устойчивого внимания');
  return focus;
};
const latestNeuroFocus=async(studentId:string)=>{
  const session=await prisma.eegSession.findFirst({where:{studentId,status:SessionStatus.COMPLETED},orderBy:{endedAt:'desc'},select:{attentionAvg:true,focusAvg:true,engagementAvg:true,relaxationAvg:true,signalAvg:true,fatigueScore:true}});
  return session?neuroFocusFromSession(session):[];
};
const adaptActivePlanByLiveEeg=async(studentId:string,session:{attentionAvg?:number|null;focusAvg?:number|null;engagementAvg?:number|null;relaxationAvg?:number|null;signalAvg?:number|null;fatigueScore?:number|null})=>{
  const neuroSkills=neuroFocusFromSession(session);
  const plan=await prisma.homeworkPlan.findFirst({where:{studentId,status:'ACTIVE'},include:{sourceDiagnostic:{select:{grade:true,language:true,gaps:true,sectionScores:true}},sourceEegSession:{select:{attentionAvg:true,focusAvg:true,engagementAvg:true,relaxationAvg:true,signalAvg:true,fatigueScore:true,endedAt:true}},tasks:{where:{completedAt:null,subject:{in:['Нейроразминка','Ми жаттығуы']}},orderBy:[{dayIndex:'asc'},{orderIndex:'asc'}]}},orderBy:{createdAt:'desc'}});
  if(!plan||!plan.tasks.length)return 0;
  const source=planSourceDefaults(plan),language=source.language==='kk'?'kk':'ru',baseGaps=Array.isArray(source.gaps)?source.gaps as string[]:[],scores=source.sectionScores as Record<string,number>;
  const generated=generateHomeworkTasks(source.grade,language,baseGaps,scores,neuroSkills).filter(task=>task.subject==='Нейроразминка'||task.subject==='Ми жаттығуы');
  const bySlot=new Map(generated.map((task:GeneratedTask)=>[`${task.dayIndex}:${task.orderIndex}`,task]));
  let changed=0;
  await prisma.$transaction(async tx=>{
    await tx.homeworkPlan.update({where:{id:plan.id},data:{focusSkills:[...new Set([...baseGaps,...neuroSkills])].slice(0,8)}});
    for(const task of plan.tasks){const next=bySlot.get(`${task.dayIndex}:${task.orderIndex}`);if(!next)continue;changed++;await tx.homeworkTask.update({where:{id:task.id},data:{skill:next.skill,prompt:next.prompt,options:next.options,correctOption:next.correctOption,hint:next.hint,explanation:next.explanation,difficulty:next.difficulty,xpReward:next.xpReward}})}
  });
  return changed;
};
const createHomeworkPlan=async(attempt:{id:string;studentId:string;grade:number;language:string;gaps:any;sectionScores:any})=>{const startsAt=schoolDayStart(),endsAt=new Date(startsAt.getTime()+7*86400000),language=attempt.language==='kk'?'kk':'ru',gaps=Array.isArray(attempt.gaps)?attempt.gaps:[],scores=attempt.sectionScores as Record<string,number>,neuroSkills=await latestNeuroFocus(attempt.studentId),generated=generateHomeworkTasks(attempt.grade,language,gaps,scores,neuroSkills),focus=[...new Set([...resolveSkillProfiles(gaps,scores,language).map(item=>item.title),...neuroSkills])].slice(0,8);return prisma.$transaction(async tx=>{await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtext(${attempt.studentId}))`;const same=await tx.homeworkPlan.findFirst({where:{studentId:attempt.studentId,sourceDiagnosticId:attempt.id},orderBy:{createdAt:'desc'}});if(same)return same;await tx.homeworkPlan.updateMany({where:{studentId:attempt.studentId,status:'ACTIVE'},data:{status:'REPLACED'}});const weekNumber=await tx.homeworkPlan.count({where:{studentId:attempt.studentId}})+1;return tx.homeworkPlan.create({data:{weekNumber,studentId:attempt.studentId,sourceDiagnosticId:attempt.id,startsAt,endsAt,focusSkills:focus,tasks:{create:generated}}})},{maxWait:10_000,timeout:30_000})};
const createLiveEegHomeworkPlan=async(session:{id:string;studentId:string;attentionAvg?:number|null;focusAvg?:number|null;engagementAvg?:number|null;relaxationAvg?:number|null;signalAvg?:number|null;fatigueScore?:number|null})=>{
  const startsAt=schoolDayStart(),endsAt=new Date(startsAt.getTime()+7*86400000),language:'ru'|'kk'='ru',grade=3,neuroSkills=neuroFocusFromSession(session),scores={math:55,logic:60,language:60},gaps=['Базовая учебная практика',...neuroSkills],generated=generateHomeworkTasks(grade,language,gaps,scores,neuroSkills),focus=[...new Set(neuroSkills)].slice(0,8);
  return prisma.$transaction(async tx=>{await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtext(${session.studentId}))`;const same=await tx.homeworkPlan.findFirst({where:{studentId:session.studentId,sourceEegSessionId:session.id},orderBy:{createdAt:'desc'}});if(same)return same;await tx.homeworkPlan.updateMany({where:{studentId:session.studentId,status:'ACTIVE'},data:{status:'REPLACED'}});const weekNumber=await tx.homeworkPlan.count({where:{studentId:session.studentId}})+1;return tx.homeworkPlan.create({data:{weekNumber,studentId:session.studentId,sourceEegSessionId:session.id,startsAt,endsAt,focusSkills:focus,tasks:{create:generated}}})},{maxWait:10_000,timeout:30_000});
};

