app.post('/api/diagnostic-bookings',auth,asyncRoute(async(req,res)=>{const input=z.object({scheduledAt:z.coerce.date(),location:z.string().trim().max(200).optional(),note:z.string().trim().max(500).optional()}).parse(req.body),studentId=await familyStudentId(req);if(!studentId)return res.status(404).json({error:'Профиль ребёнка не привязан'});if(input.scheduledAt.getTime()<Date.now()+60*60_000)return res.status(400).json({error:'Выберите время минимум через один час'});const conflict=await prisma.diagnosticBooking.findFirst({where:{studentId,scheduledAt:{gte:new Date(input.scheduledAt.getTime()-45*60_000),lte:new Date(input.scheduledAt.getTime()+45*60_000)},status:{in:['BOOKED','CONFIRMED']}}});if(conflict)return res.status(409).json({error:'На это время уже есть запись'});const booking=await prisma.diagnosticBooking.create({data:{studentId,createdById:req.user!.id,scheduledAt:input.scheduledAt,location:input.location,note:input.note}});return res.status(201).json({booking})}));
