app.get('/api/v2/analytics',auth,asyncRoute(async(req,res)=>{const where=await sessionScope(req);const sessions=await prisma.eegSession.findMany({where:{...where,status:SessionStatus.COMPLETED},include:{student:{select:{firstName:true,lastName:true}}},orderBy:{startedAt:'asc'},take:300});const daily=new Map<string,{attention:number;engagement:number;focus:number;fatigue:number;count:number}>();for(const session of sessions){const key=session.startedAt.toISOString().slice(0,10);const item=daily.get(key)||{attention:0,engagement:0,focus:0,fatigue:0,count:0};item.attention+=session.attentionAvg||0;item.engagement+=session.engagementAvg||0;item.focus+=session.focusAvg||0;item.fatigue+=session.fatigueScore||0;item.count++;daily.set(key,item)}const timeline=[...daily.entries()].slice(-30).map(([date,item])=>({date,attention:Math.round(item.attention/item.count),engagement:Math.round(item.engagement/item.count),focus:Math.round(item.focus/item.count),fatigue:Math.round(item.fatigue/item.count),sessions:item.count}));const recent=sessions.slice(-8).reverse().map(session=>({id:session.id,student:`${session.student.firstName} ${session.student.lastName}`,date:session.startedAt,attention:Math.round(session.attentionAvg||0),engagement:Math.round(session.engagementAvg||0),focus:Math.round(session.focusAvg||0),fatigue:Math.round(session.fatigueScore||0),summary:session.aiSummary,recommendations:session.aiRecommendations}));return res.json({timeline,recent,total:sessions.length})}));

app.post('/api/devices/:id/heartbeat',auth,requireStudent,asyncRoute(async(req,res)=>{
  const updated=await prisma.device.updateMany({where:{id:String(req.params.id),connectedByUserId:req.user!.id},data:{lastSeenAt:new Date()}});
  return updated.count?res.json({ok:true}):res.status(404).json({error:'Устройство не найдено'});
}));

app.get('/api/v2/device-status',auth,requireTeacher,asyncRoute(async(req,res)=>{
  const devices=await prisma.device.findMany({where:{organizationId:req.user!.organizationId},orderBy:{lastSeenAt:'desc'}});
  const students=await prisma.student.findMany({where:{class:{organizationId:req.user!.organizationId}},select:{id:true,firstName:true,lastName:true,class:{select:{name:true}}},orderBy:{lastName:'asc'}});
  const staleBefore=Date.now()-15000;
  const byStudent=new Map(devices.filter(device=>device.connectedStudentId).map(device=>[device.connectedStudentId,device]));
  return res.json({devices:students.map(student=>{const device=byStudent.get(student.id);return device?{...device,status:device.lastSeenAt&&device.lastSeenAt.getTime()>=staleBefore?device.status:'OFFLINE',student}:{id:`student-${student.id}`,name:'Устройство не зарегистрировано',serialNumber:'Нет устройства',firmware:null,status:'OFFLINE',lastSeenAt:null,student}})});
}));
app.get('/api/notifications',auth,asyncRoute(async(req,res)=>{
  const where=await sessionScope(req);
  const sessions=await prisma.eegSession.findMany({where:{...where,status:SessionStatus.COMPLETED},include:{student:{select:{firstName:true,lastName:true}}},orderBy:{endedAt:'desc'},take:12});
  const items=sessions.map(session=>({id:`session-${session.id}`,type:'REPORT',title:/контрольн.*диагностик/i.test(session.subject||'')?'Ученик прошёл контрольную точку':'EEG-отчёт готов',message:`${session.student.firstName} ${session.student.lastName}: фокус ${Math.round(session.focusAvg||0)}%, +${session.xpAwarded} XP`,createdAt:session.endedAt||session.createdAt,action:/контрольн.*диагностик/i.test(session.subject||'')?'Мой план':'Отчёты'}));
  if(req.user!.role==='STUDENT'){
    const student=await prisma.student.findUnique({where:{userId:req.user!.id},select:{level:true,xp:true,streak:true,lastHomeworkAt:true,updatedAt:true,homeworkPlans:{where:{status:'ACTIVE'},orderBy:{createdAt:'desc'},take:1,select:{id:true,startsAt:true,checkIn:{select:{id:true,totalScore:true,baselineDelta:true,completedAt:true}},tasks:{select:{dayIndex:true,completedAt:true}}}}}});
    if(student){const streak=liveStreak(student);items.unshift({id:`level-${student.level}-${Math.floor(student.xp/100)}`,type:'PROGRESS',title:`Вы на Level ${student.level}`,message:`${Math.max(0,student.level*500-student.xp)} XP до следующего уровня`,createdAt:student.updatedAt,action:'Мотивация'});if(streak>0)items.unshift({id:`streak-${streak}`,type:'PROGRESS',title:`Серия: ${streak} дней`,message:'Сделайте короткое задание сегодня, чтобы сохранить ритм.',createdAt:student.updatedAt,action:'Мой план'});const plan=student.homeworkPlans[0];if(plan){const availability=checkInAvailability(plan),day=availability.availableDay,todayTasks=plan.tasks.filter(task=>task.dayIndex===day),remaining=todayTasks.filter(task=>!task.completedAt).length;items.unshift({id:`homework-${plan.id}-${day}-${remaining}`,type:'PROGRESS',title:remaining?'Задание на сегодня готово':'Дневная цель выполнена',message:remaining?`${remaining} коротких заданий · примерно ${Math.max(5,remaining*3)} минут`:`Отлично! День ${day+1} из 7 закрыт.`,createdAt:student.updatedAt,action:'Мой план'});if(plan.checkIn)items.unshift({id:`checkin-${plan.checkIn.id}`,type:'REPORT',title:'Контрольная точка сохранена',message:`Результат ${plan.checkIn.totalScore}% · ${plan.checkIn.baselineDelta>=0?'+':''}${plan.checkIn.baselineDelta}% к старту`,createdAt:plan.checkIn.completedAt,action:'Мой план'});else if(availability.unlocked)items.unshift({id:`checkin-ready-${plan.id}`,type:'PROGRESS',title:'Открылась контрольная диагностика',message:'6 вопросов + короткая EEG-запись помогут точнее настроить оставшуюся неделю.',createdAt:student.updatedAt,action:'Мой план'})}}
  }
  if(req.user!.role==='TEACHER'||req.user!.role==='ADMIN'){
    const active=await prisma.device.findMany({where:{organizationId:req.user!.organizationId,status:{in:['ONLINE','IN_SESSION']}},take:8,orderBy:{lastSeenAt:'desc'}});
    items.unshift(...active.map(device=>({id:`device-${device.id}`,type:'DEVICE',title:device.status==='IN_SESSION'?'Ученик начал EEG-сессию':'Устройство подключено',message:`${device.name} · ${device.serialNumber} · v${device.firmware||'—'}`,createdAt:device.lastSeenAt||device.createdAt,action:'Обзор'})));
    const support=await prisma.student.findMany({where:{class:{organizationId:req.user!.organizationId},homeworkPlans:{some:{status:'ACTIVE'}}},select:{firstName:true,lastName:true,updatedAt:true,homeworkPlans:{where:{status:'ACTIVE'},take:1,orderBy:{createdAt:'desc'},select:{tasks:{select:{completedAt:true}}}}},take:20});const behind=support.filter(student=>{const tasks=student.homeworkPlans[0]?.tasks||[];return tasks.length&&tasks.filter(task=>task.completedAt).length/tasks.length<.2});if(behind.length)items.unshift({id:`support-${behind.map(item=>item.firstName).join('-')}`,type:'PROGRESS',title:`${behind.length} ученик(а) нуждаются в поддержке`,message:`Низкий прогресс недели: ${behind.slice(0,3).map(item=>`${item.firstName} ${item.lastName}`).join(', ')}`,createdAt:new Date(),action:'Мой план'});
  }
  return res.json({notifications:items.sort((a,b)=>new Date(b.createdAt).getTime()-new Date(a.createdAt).getTime()).slice(0,20)});
}));

app.get('/api/achievements',auth,requireStudent,asyncRoute(async(req,res)=>{const student=await prisma.student.findUnique({where:{userId:req.user!.id},include:{sessions:{where:{status:SessionStatus.COMPLETED},select:{focusAvg:true,engagementAvg:true,startedAt:true}},homeworkPlans:{include:{tasks:{select:{dayIndex:true,completedAt:true,attempts:{select:{correct:true,usedHint:true}}}}}}}});if(!student)return res.status(404).json({error:'Профиль ученика не найден'});const diagnosticCount=await prisma.diagnosticAttempt.count({where:{studentId:student.id}});const streak=liveStreak(student),sessions=student.sessions;const tasks=student.homeworkPlans.flatMap(plan=>plan.tasks),completed=tasks.filter(task=>task.completedAt),perfect=completed.filter(task=>task.attempts.length===1&&task.attempts[0]?.correct&&!task.attempts[0]?.usedHint).length;const completedDays=new Set(student.homeworkPlans.flatMap(plan=>{const days=new Map<number,boolean>();plan.tasks.forEach(task=>days.set(task.dayIndex,(days.get(task.dayIndex)??true)&&Boolean(task.completedAt)));return [...days].filter(([,done])=>done).map(([day])=>`${plan.id}-${day}`)})).size;const bestFocus=Math.round(Math.max(0,...sessions.map(item=>item.focusAvg||0)));const bestEngagement=Math.round(Math.max(0,...sessions.map(item=>item.engagementAvg||0)));const definitions=[{id:'first-diagnostic',icon:'brain',title:'Моя точка старта',description:'Пройти первую комплексную диагностику',unlocked:diagnosticCount>=1,progress:Math.min(1,diagnosticCount),target:1},{id:'first-homework',icon:'book',title:'Первый шаг',description:'Выполнить первое микро-задание',unlocked:completed.length>=1,progress:Math.min(1,completed.length),target:1},{id:'perfect-5',icon:'target',title:'Точно в цель',description:'Решить 5 заданий с первой попытки без подсказки',unlocked:perfect>=5,progress:perfect,target:5},{id:'week-path',icon:'star',title:'Неделя силы',description:'Полностью закрыть 7 учебных дней',unlocked:completedDays>=7,progress:completedDays,target:7},{id:'first-eeg',icon:'brain',title:'Первая EEG-сессия',description:'Завершить первый нейроанализ',unlocked:sessions.length>=1,progress:Math.min(1,sessions.length),target:1},{id:'focus-90',icon:'target',title:'Фокус выше 90%',description:'Достичь высокой концентрации',unlocked:bestFocus>=90,progress:bestFocus,target:90},{id:'streak-7',icon:'flame',title:'7 дней подряд',description:'Поддерживать регулярную серию',unlocked:streak>=7,progress:student.streak,target:7},{id:'engagement-85',icon:'star',title:'Высокая вовлечённость',description:'Получить вовлечённость выше 85%',unlocked:bestEngagement>=85,progress:bestEngagement,target:85},{id:'level-5',icon:'award',title:'Level 5',description:'Накопить 2000 XP',unlocked:student.level>=5,progress:student.xp,target:2000}];return res.json({student:{xp:student.xp,level:student.level,streak,sessions:sessions.length,homeworkCompleted:completed.length},achievements:definitions,unlocked:definitions.filter(item=>item.unlocked).length})}));

app.get('/api/motivation',auth,requireStudent,asyncRoute(async(req,res)=>{const student=await prisma.student.findUnique({where:{userId:req.user!.id},select:{firstName:true,xp:true,level:true,streak:true,lastHomeworkAt:true,weeklyGoal:true,sessions:{where:{status:SessionStatus.COMPLETED,startedAt:{gte:new Date(Date.now()-30*86400000)}},orderBy:{startedAt:'desc'},select:{startedAt:true,attentionAvg:true,engagementAvg:true,focusAvg:true,xpAwarded:true}}}});if(!student)return res.status(404).json({error:'Профиль ученика не найден'});const dates=[...new Set(student.sessions.map(session=>session.startedAt.toISOString().slice(0,10)))];const weekStart=new Date();weekStart.setUTCHours(0,0,0,0);weekStart.setUTCDate(weekStart.getUTCDate()-((weekStart.getUTCDay()+6)%7));const weekDates=dates.filter(date=>new Date(`${date}T00:00:00Z`)>=weekStart);const latest=student.sessions[0];const previous=student.sessions[1];const delta=latest&&previous?Math.round((latest.focusAvg||0)-(previous.focusAvg||0)):0;const messages=[latest?`Последний фокус — ${Math.round(latest.focusAvg||0)}%.`:'Завершите первую EEG-сессию, чтобы начать личную динамику.',delta>0?`Фокус улучшился на ${delta}% относительно предыдущего занятия.`:delta<0?'Сегодня выберите короткую сессию и начните со знакомого задания.':'Регулярные короткие занятия помогают увидеть устойчивую динамику.',`${Math.max(0,student.level*500-student.xp)} XP до Level ${student.level+1}.`];return res.json({student:{firstName:student.firstName,xp:student.xp,level:student.level,streak:liveStreak(student),weeklyGoal:student.weeklyGoal},activeDates:dates,weekSessions:weekDates.length,recent:student.sessions.slice(0,7),messages})}));
app.patch('/api/motivation/goal',auth,requireStudent,asyncRoute(async(req,res)=>{const {weeklyGoal}=z.object({weeklyGoal:z.union([z.literal(3),z.literal(5),z.literal(7)])}).parse(req.body);const updated=await prisma.student.updateMany({where:{userId:req.user!.id},data:{weeklyGoal}});return updated.count?res.json({weeklyGoal}):res.status(404).json({error:'Профиль ученика не найден'})}));

app.get('/api/class-progress',auth,requireTeacher,asyncRoute(async(req,res)=>{const since=new Date(Date.now()-7*86400000);const students=await prisma.student.findMany({where:{class:{organizationId:req.user!.organizationId}},select:{id:true,publicId:true,firstName:true,lastName:true,xp:true,level:true,streak:true,class:{select:{id:true,name:true}},sessions:{where:{status:SessionStatus.COMPLETED},orderBy:{startedAt:'desc'},take:12,select:{startedAt:true,focusAvg:true,attentionAvg:true,engagementAvg:true}}},orderBy:{lastName:'asc'}});const rows=students.map(student=>{const week=student.sessions.filter(session=>session.startedAt>=since);const avg=(key:'focusAvg'|'attentionAvg'|'engagementAvg')=>week.length?Math.round(week.reduce((sum,item)=>sum+(item[key]||0),0)/week.length):0;return{id:student.id,publicId:student.publicId,name:`${student.firstName} ${student.lastName}`,initials:`${student.firstName[0]}${student.lastName[0]}`,class:student.class,level:student.level,xp:student.xp,streak:student.streak,weekSessions:week.length,focus:avg('focusAvg'),attention:avg('attentionAvg'),engagement:avg('engagementAvg'),lastSession:student.sessions[0]?.startedAt||null,status:!student.sessions.length?'NEW':week.length===0?'NEEDS_ATTENTION':avg('focusAvg')>=80?'EXCELLENT':'ACTIVE'}});return res.json({students:rows,summary:{active:rows.filter(row=>row.weekSessions>0).length,excellent:rows.filter(row=>row.status==='EXCELLENT').length,needsAttention:rows.filter(row=>row.status==='NEEDS_ATTENTION').length,averageStreak:rows.length?Math.round(rows.reduce((sum,row)=>sum+row.streak,0)/rows.length):0}})}));

app.post('/api/auth/password',auth,asyncRoute(async(req,res)=>{const input=z.object({currentPassword:z.string().min(1),newPassword:z.string().min(10).max(128)}).parse(req.body);const user=await prisma.user.findUnique({where:{id:req.user!.id},select:{passwordHash:true}});if(!user||!await bcrypt.compare(input.currentPassword,user.passwordHash))return res.status(400).json({error:'Текущий пароль указан неверно'});await prisma.user.update({where:{id:req.user!.id},data:{passwordHash:await bcrypt.hash(input.newPassword,12)}});return res.json({ok:true})}));

app.get('/api/account/export',auth,asyncRoute(async(req,res)=>{const user=await prisma.user.findUnique({where:{id:req.user!.id},select:{id:true,email:true,firstName:true,lastName:true,role:true,createdAt:true,organization:{select:{id:true,name:true}}}});if(!user)return res.status(404).json({error:'Аккаунт не найден'});let data:unknown=null;if(req.user!.role==='STUDENT'){data=await prisma.student.findUnique({where:{userId:req.user!.id},include:{class:{select:{name:true,subject:true,academicYear:true}},sessions:{where:{status:SessionStatus.COMPLETED},orderBy:{startedAt:'desc'},select:{id:true,subject:true,startedAt:true,endedAt:true,attentionAvg:true,meditationAvg:true,engagementAvg:true,focusAvg:true,relaxationAvg:true,signalAvg:true,fatigueScore:true,emotionalState:true,aiSummary:true,aiRecommendations:true,xpAwarded:true}}}})}else if(req.user!.role==='PARENT'){const parent=await prisma.user.findUnique({where:{id:req.user!.id},select:{parentStudentId:true}});data=parent?.parentStudentId?await prisma.student.findUnique({where:{id:parent.parentStudentId},select:{publicId:true,firstName:true,lastName:true,age:true,school:true,class:{select:{name:true}},sessions:{where:{status:SessionStatus.COMPLETED},orderBy:{startedAt:'desc'},select:{startedAt:true,endedAt:true,attentionAvg:true,engagementAvg:true,focusAvg:true,aiSummary:true,aiRecommendations:true}}}}):null}else{data=await prisma.organization.findUnique({where:{id:req.user!.organizationId!},select:{id:true,name:true,classes:{orderBy:{createdAt:'desc'},select:{id:true,name:true,subject:true,academicYear:true,archived:true,inviteCode:true,_count:{select:{students:true,sessions:true}}}}}})}res.setHeader('Content-Disposition',`attachment; filename="iui-account-${new Date().toISOString().slice(0,10)}.json"`);return res.json({exportedAt:new Date().toISOString(),account:user,data})}));

app.post('/api/auth/register',asyncRoute(async(req,res)=>{const input=z.object({email:z.string().email(),password:z.string().min(10).max(128),firstName:z.string().trim().min(2).max(80),lastName:z.string().trim().min(2).max(80),role:z.enum(['TEACHER','STUDENT','PARENT']),inviteCode:z.string().trim().optional(),organizationName:z.string().trim().max(120).optional()}).parse(req.body);if(input.role==='TEACHER'&&(!input.organizationName||input.organizationName.length<2))return res.status(400).json({error:'Укажите название школы или учебного центра'});const email=input.email.toLowerCase();if(await prisma.user.findUnique({where:{email}}))return res.status(409).json({error:'Пользователь уже существует'});let targetClass:any=null,invite:any=null;if(input.role==='STUDENT'){if(!input.inviteCode)return res.status(400).json({error:'Введите код класса'});targetClass=await prisma.class.findUnique({where:{inviteCode:input.inviteCode.toUpperCase()}});if(!targetClass||targetClass.archived)return res.status(400).json({error:'Код класса недействителен'})}if(input.role==='PARENT'){if(!input.inviteCode)return res.status(400).json({error:'Введите персональный код приглашения'});invite=await prisma.invite.findUnique({where:{code:input.inviteCode.toUpperCase()}});if(!invite||invite.usedAt||invite.expiresAt<new Date()||invite.role!==Role.PARENT||!invite.studentId)return res.status(400).json({error:'Код приглашения недействителен или истёк'});if(invite.email&&invite.email.toLowerCase()!==email)return res.status(400).json({error:'Используйте email, на который преподаватель создал приглашение'})}const passwordHash=await bcrypt.hash(input.password,12);try{const user=await prisma.$transaction(async tx=>{let organizationId=targetClass?.organizationId||invite?.organizationId;if(input.role==='TEACHER'){const organization=await tx.organization.create({data:{name:input.organizationName||`${input.firstName} Academy`}});organizationId=organization.id}const created=await tx.user.create({data:{email,passwordHash,firstName:input.firstName,lastName:input.lastName,role:input.role as Role,organizationId,parentStudentId:invite?.studentId||null}});if(targetClass)await tx.student.create({data:{userId:created.id,firstName:input.firstName,lastName:input.lastName,classId:targetClass.id,school:'',publicId:`IUI-${crypto.randomUUID().slice(0,8).toUpperCase()}`}});if(invite)await tx.invite.update({where:{id:invite.id},data:{usedAt:new Date()}});return created});setSession(res,tokenFor(user));return res.status(201).json({user:{id:user.id,email:user.email,firstName:user.firstName,lastName:user.lastName,role:user.role}})}catch(error){if(error instanceof Prisma.PrismaClientKnownRequestError&&error.code==='P2002')return res.status(409).json({error:'Такой аккаунт или профиль уже существует'});throw error}}));

