app.post('/api/public/diagnostics/score',asyncRoute(async(req,res)=>{
  const input=z.object({grade:z.number().int().min(1).max(11),language:z.enum(['ru','kk']),assessmentId:z.string().regex(/^\d+$/),answers:z.record(z.string(),z.number().int().min(0).max(3)),responses:z.array(z.object({questionId:z.string(),answer:z.number().int().min(0).max(3),responseTimeMs:z.number().int().min(0).max(3_600_000),changes:z.number().int().min(0).max(100),timeout:z.boolean(),startedAt:z.string(),answeredAt:z.string().optional()})).max(30)}).parse(req.body);
  const questions=diagnosticQuestions(input.grade,input.language,Number(input.assessmentId)),ids=new Set(questions.map(item=>item.id));
  if(Object.keys(input.answers).length!==questions.length||Object.keys(input.answers).some(id=>!ids.has(id)))return res.status(400).json({error:'Ответьте на все вопросы диагностики'});
  const result=scoreAdaptiveDiagnostic(questions,input.answers,input.responses);
  return res.json({result:{...result,grade:input.grade,language:input.language,completedAt:new Date().toISOString()},anonymous:true,stored:false});
}));

app.get('/api/diagnostics/questions',auth,requireStudent,asyncRoute(async(req,res)=>{
  const input=z.object({grade:z.coerce.number().int().min(1).max(11),language:z.enum(['ru','kk'])}).parse(req.query);
  const profile=await prisma.student.findUnique({where:{userId:req.user!.id},select:{class:{select:{name:true}}}});
  const profileGrade=Number(profile?.class?.name.match(/\d{1,2}/)?.[0]);
  if(profileGrade>=1&&profileGrade<=11&&input.grade!==profileGrade)return res.status(400).json({error:`Диагностика должна соответствовать ${profileGrade} классу из профиля`});
  const seed=Date.now(),fullQuestions=diagnosticQuestions(input.grade,input.language,seed),questions=fullQuestions.map(({correct,explanation,...item})=>item);
  return res.json({assessmentId:`${seed}`,questions,sections:[{id:'math',title:'Когнитивная математика',minutes:15},{id:'logic',title:'Логика и внимание',minutes:15},{id:'language',title:input.language==='kk'?'Ақпаратты түсіну':'Понимание информации',minutes:15}],totalMinutes:45,adaptive:{levels:5,gradeIsStartingPoint:true}});
}));
app.post('/api/diagnostics/adapt',auth,requireStudent,asyncRoute(async(req,res)=>{
  const input=z.object({grade:z.number().int().min(1).max(11),language:z.enum(['ru','kk']),assessmentId:z.string(),questionId:z.string(),answer:z.number().int().min(0).max(3),remainingIds:z.array(z.string()).max(30)}).parse(req.body);
  const bank=diagnosticQuestions(input.grade,input.language,Number(input.assessmentId)),current=bank.find(item=>item.id===input.questionId);
  if(!current)return res.status(400).json({error:'Задание не относится к этой диагностике'});
  const correct=input.answer===current.correct,targetLevel=Math.max(1,Math.min(5,(current.difficulty||1)+(correct?1:-1))),remaining=bank.filter(item=>input.remainingIds.includes(item.id)&&item.section===current.section);
  const ranked=[...remaining].sort((a,b)=>Number(b.category===current.category)-Number(a.category===current.category)||Math.abs((a.difficulty||1)-targetLevel)-Math.abs((b.difficulty||1)-targetLevel));
  return res.json({nextQuestionId:ranked[0]?.id||null});
}));
