const careerLabels:Record<string,string>={research:'исследования',creative:'создание новых решений',social:'обучение и помощь людям',technical:'инженерные проекты',leadership:'управление и предпринимательство',analytical:'аналитика и данные'};
app.get('/api/career-profile',auth,asyncRoute(async(req,res)=>{
  if(req.user!.role==='TEACHER'||req.user!.role==='ADMIN'){
    const students=await prisma.student.findMany({where:{class:{organizationId:req.user!.organizationId}},select:{id:true,firstName:true,lastName:true,publicId:true,class:{select:{name:true}},comments:{where:{OR:[{text:{startsWith:'[CAREER_PROFILE]'}},{text:{startsWith:'[CAREER_REVIEW]'}}]},orderBy:{createdAt:'desc'}}},orderBy:[{class:{name:'asc'}},{lastName:'asc'}]});
    const profiles=students.map(student=>{const parse=(prefix:string)=>{const raw=student.comments.find(item=>item.text.startsWith(prefix))?.text.slice(prefix.length);try{return raw?JSON.parse(raw):null}catch{return null}};const grade=Number(student.class?.name.match(/\d{1,2}/)?.[0])||0;return{id:student.id,name:`${student.firstName} ${student.lastName}`,publicId:student.publicId,className:student.class?.name||'Без класса',grade,eligible:true,early:grade>0&&grade<7,profile:parse('[CAREER_PROFILE]'),review:parse('[CAREER_REVIEW]')}});
    return res.json({mode:'teacher',profiles});
  }
  const linkedId=req.user!.role==='PARENT'?(await prisma.user.findUnique({where:{id:req.user!.id},select:{parentStudentId:true}}))?.parentStudentId:null;
  const careerInclude={class:{select:{name:true}},comments:{where:{text:{startsWith:'[CAREER_PROFILE]'}},orderBy:{createdAt:'desc' as const},take:1}};
  const student=req.user!.role==='STUDENT'?await prisma.student.findUnique({where:{userId:req.user!.id},include:careerInclude}):linkedId?await prisma.student.findUnique({where:{id:linkedId},include:careerInclude}):null;
  if(!student)return res.json({eligible:false,reason:'Профориентация доступна ученику и связанному родителю'});
  const grade=Number(student.class?.name.match(/\d{1,2}/)?.[0])||0,raw=student.comments[0]?.text.replace('[CAREER_PROFILE]','');let profile=null;try{profile=raw?JSON.parse(raw):null}catch{}
  return res.json({eligible:true,early:grade>0&&grade<7,grade,profile});
}));
