app.get('/api/homework-plan',auth,asyncRoute(async(req,res)=>{
  const student=await homeworkOwner(req,typeof req.query.studentId==='string'?req.query.studentId:undefined);
  if(!student)return res.status(404).json({error:req.user!.role==='STUDENT'?'Профиль ученика не найден':'Ученик не найден'});
  let plan=await prisma.homeworkPlan.findFirst({where:{studentId:student.id,status:'ACTIVE'},include:homeworkPlanInclude,orderBy:{createdAt:'desc'}});
  if(plan&&!plan.tasks.some(task=>task.subject==='Нейроразминка'||task.subject==='Ми жаттығуы')){
    const source=planSourceDefaults(plan),language=source.language==='kk'?'kk':'ru',gaps=Array.isArray(source.gaps)?source.gaps as string[]:[],neuroSkills=plan.sourceEegSession?neuroFocusFromSession(plan.sourceEegSession):[],generated=generateHomeworkTasks(source.grade,language,gaps,source.sectionScores as Record<string,number>,neuroSkills),cognitive=generated.filter(task=>task.subject==='Нейроразминка'||task.subject==='Ми жаттығуы');
    await prisma.$transaction(async tx=>{await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtext(${plan!.id}))`;const existing=await tx.homeworkTask.count({where:{planId:plan!.id,subject:{in:['Нейроразминка','Ми жаттығуы']}}});if(!existing)await tx.homeworkTask.createMany({data:cognitive.map(task=>({...task,planId:plan!.id}))})});
    plan=await prisma.homeworkPlan.findFirst({where:{id:plan.id},include:homeworkPlanInclude});
  }
  return plan?res.json({plan:planPayload(plan),student:{id:student.id,firstName:student.firstName,lastName:student.lastName,xp:student.xp,level:student.level,streak:liveStreak(student)}}):res.status(404).json({error:'Диагностика сохранена, но активный план не найден. Нажмите «Восстановить план»'});
}));
app.post('/api/homework-plans/generate',auth,requireStudent,asyncRoute(async(req,res)=>{const student=await prisma.student.findUnique({where:{userId:req.user!.id}});if(!student)return res.status(404).json({error:'Профиль ученика не найден'});const existing=await prisma.homeworkPlan.findFirst({where:{studentId:student.id,status:'ACTIVE'},orderBy:{createdAt:'desc'}});if(existing)return res.json({planId:existing.id,created:false});const diagnostic=await prisma.diagnosticAttempt.findFirst({where:{studentId:student.id},orderBy:{completedAt:'desc'}}),latestEeg=await prisma.eegSession.findFirst({where:{studentId:student.id,status:SessionStatus.COMPLETED},orderBy:{endedAt:'desc'},select:{id:true,studentId:true,attentionAvg:true,focusAvg:true,engagementAvg:true,relaxationAvg:true,signalAvg:true,fatigueScore:true}});if(!diagnostic&&!latestEeg)return res.status(400).json({error:'Персональный план создаётся после первой диагностики или Live EEG-сессии'});const previous=await prisma.homeworkPlan.findFirst({where:{studentId:student.id},orderBy:{createdAt:'desc'},select:{sourceDiagnosticId:true,sourceEegSessionId:true,status:true}});if(diagnostic&&previous?.sourceDiagnosticId===diagnostic.id)return res.status(409).json({error:'Неделя завершена — пора пройти повторную диагностику или Live EEG, чтобы обновить план'});if(!diagnostic&&latestEeg&&previous?.sourceEegSessionId===latestEeg.id)return res.status(409).json({error:'Неделя завершена — пора пройти новую Live EEG-сессию, чтобы обновить план'});const plan=diagnostic?await createHomeworkPlan(diagnostic):await createLiveEegHomeworkPlan(latestEeg!);return res.status(201).json({planId:plan.id,created:true,source:diagnostic?'diagnostic':'live-eeg'})}));
app.post('/api/homework-tasks/:id/answer',auth,requireStudent,asyncRoute(async(req,res)=>{
  const input=z.object({selectedOption:z.number().int().min(0).max(3),usedHint:z.boolean().default(false),responseTimeMs:z.number().int().min(0).max(3600000).optional()}).parse(req.body);
  const task=await prisma.homeworkTask.findFirst({where:{id:String(req.params.id),plan:{status:'ACTIVE',student:{userId:req.user!.id}}},include:{plan:true}});
  if(!task)return res.status(404).json({error:'Задание не найдено'});
  const availableDay=Math.max(0,Math.min(6,schoolDayDistance(new Date(),task.plan.startsAt)));
  if(task.dayIndex>availableDay)return res.status(403).json({error:'Это задание откроется позже'});
  const correct=input.selectedOption===task.correctOption,now=new Date();
  await prisma.homeworkAttempt.create({data:{taskId:task.id,selectedOption:input.selectedOption,correct,usedHint:input.usedHint,responseTimeMs:input.responseTimeMs}});
  let reward=0,dayCompleted=false,studentUpdate:any=null;const milestones:string[]=[];
  if(correct){
    const outcome=await prisma.$transaction(async tx=>{
      await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtext(${task.plan.studentId}))`;
      const claimed=await tx.homeworkTask.updateMany({where:{id:task.id,completedAt:null},data:{completedAt:now}});
      if(claimed.count===0)return null;
      const student=await tx.student.findUnique({where:{id:task.plan.studentId}});if(!student)return null;
      const incomplete=await tx.homeworkTask.count({where:{planId:task.planId,dayIndex:task.dayIndex,completedAt:null}}),completedDay=incomplete===0;
      const earned=Math.max(3,task.xpReward-(input.usedHint?3:0)),xp=student.xp+earned,level=Math.floor(xp/500)+1;
      let streak=student.streak;if(completedDay){const gap=student.lastHomeworkAt?schoolDayDistance(now,student.lastHomeworkAt):999;streak=gap===0?Math.max(1,streak):gap===1?streak+1:1}
      const updated=await tx.student.update({where:{id:student.id},data:{xp,level,streak,...(completedDay?{lastHomeworkAt:now,homeworkCompleted:{increment:1}}:{})},select:{xp:true,level:true,streak:true,homeworkCompleted:true}});
      const completedTotal=await tx.homeworkTask.count({where:{plan:{studentId:student.id},completedAt:{not:null}}});
      return{earned,completedDay,updated,student,level,completedTotal};
    },{maxWait:10_000,timeout:30_000});
    if(outcome){reward=outcome.earned;dayCompleted=outcome.completedDay;studentUpdate=outcome.updated;if(outcome.completedTotal===1)milestones.push('Первое микро-задание');if(dayCompleted&&outcome.student.homeworkCompleted===0)milestones.push('Первый учебный день');if(outcome.level>outcome.student.level)milestones.push('Новый уровень')}
  }
  return res.json({correct,correctOption:task.correctOption,explanation:task.explanation,reward,dayCompleted,student:studentUpdate,milestones});
}));
