const cleanupStaleState=async()=>{const now=new Date();await prisma.$transaction([prisma.eegSession.updateMany({where:{status:SessionStatus.ACTIVE,startedAt:{lt:new Date(now.getTime()-6*60*60_000)}},data:{status:SessionStatus.CANCELLED,endedAt:now}}),prisma.device.updateMany({where:{status:{in:['ONLINE','IN_SESSION']},lastSeenAt:{lt:new Date(now.getTime()-60_000)}},data:{status:'OFFLINE'}})]).catch(error=>console.error('Stale-state cleanup failed',error))};void cleanupStaleState();const cleanupTimer=setInterval(cleanupStaleState,60_000);cleanupTimer.unref();
let shuttingDown=false;const shutdown=async()=>{if(shuttingDown)return;shuttingDown=true;clearInterval(cleanupTimer);await prisma.$disconnect();httpServer.close(()=>process.exit(0));setTimeout(()=>process.exit(1),5000).unref()};
process.on('SIGTERM',shutdown);process.on('SIGINT',shutdown);
